def longest_valid_prefix(s: str) -> int:
    balance = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch == '<':
            balance += 1
        else:
            balance -= 1
            if balance < 0:
                break
            if balance == 0:
                max_len = i + 1
    return max_len
